// Valida el cuerpo {"preguntas":["…"]} antes de gastar cuota.
const body = $('Webhook').first().json.body ?? {};
const preguntas = body.preguntas;
if (!Array.isArray(preguntas) || preguntas.length === 0) {
  throw new Error('El cuerpo debe traer "preguntas": una lista no vacía de textos');
}
if (preguntas.length > 20) {
  throw new Error(`Se aceptan hasta 20 preguntas por llamada y llegaron ${preguntas.length}`);
}
const limpias = preguntas.map((p, i) => {
  if (typeof p !== 'string' || !p.trim()) {
    throw new Error(`La pregunta ${i} está vacía o no es texto`);
  }
  return p.trim();
});
return [{ json: { preguntas: limpias } }];

// Comprueba que la colección exista, tenga la configuración de C9 y tenga puntos; luego arma el cuerpo de embeddings.
const { coleccion, dimensionVector, modeloEmbeddings } = $('Configuración').first().json;
const resp = $input.first().json;
if (resp.statusCode === 404) {
  throw new Error(`La colección ${coleccion} no existe en Qdrant; ejecuta antes el flujo «RutaIA - Indexación de cursos»`);
}
if (resp.statusCode !== 200) {
  throw new Error(`Qdrant respondió HTTP ${resp.statusCode} al leer la colección ${coleccion}: ${JSON.stringify(resp.body?.status ?? resp.body)}`);
}
const v = resp.body?.result?.config?.params?.vectors;
if (!v || v.size !== dimensionVector || v.distance !== 'Cosine') {
  throw new Error(`La colección ${coleccion} tiene otra configuración (${JSON.stringify(v)}); se esperaba size ${dimensionVector} y distance Cosine`);
}
const puntos = resp.body?.result?.points_count;
if (!Number.isInteger(puntos) || puntos < 1) {
  throw new Error(`La colección ${coleccion} no tiene puntos; ejecuta antes el flujo «RutaIA - Indexación de cursos»`);
}
// C9: la pregunta con trim, sin prefijos, con input_type query.
return [{
  json: {
    cuerpo: {
      model: modeloEmbeddings,
      input: $('Validar preguntas').first().json.preguntas,
      input_type: 'query',
      encoding_format: 'float',
    },
  },
}];

// Comprueba la respuesta de OpenRouter y arma una búsqueda de calibración por pregunta (C9: limit 10, sin score_threshold).
const { dimensionVector } = $('Configuración').first().json;
const preguntas = $('Validar preguntas').first().json.preguntas;
const resp = $input.first().json;
const body = resp.body ?? {};
if (resp.statusCode !== 200 || body.error) {
  const codigo = body.error?.code ?? resp.statusCode;
  const pistas = {
    429: 'cuota de la capa gratuita agotada o proveedor saturado; reintenta más tarde',
    404: 'ruta :free no disponible; revisa la privacidad en https://openrouter.ai/settings/privacy',
    402: 'saldo negativo en la cuenta de OpenRouter',
  };
  const detalle = body.error?.message ?? JSON.stringify(body).slice(0, 300);
  const pista = pistas[codigo] ? ` (${pistas[codigo]})` : '';
  throw new Error(`OpenRouter respondió HTTP ${codigo} en /embeddings: ${detalle}${pista}`);
}
const data = body.data;
if (!Array.isArray(data) || data.length !== preguntas.length) {
  throw new Error(`OpenRouter devolvió ${Array.isArray(data) ? data.length : 0} vectores para ${preguntas.length} preguntas`);
}
const ordenados = [...data].sort((a, b) => a.index - b.index);
ordenados.forEach((d, i) => {
  if (d.index !== i) {
    throw new Error(`Los índices de OpenRouter no son 0..${preguntas.length - 1} (falta el ${i})`);
  }
  const v = d.embedding;
  if (!Array.isArray(v) || v.length !== dimensionVector || !v.every(Number.isFinite)) {
    throw new Error(`El vector ${i} («${preguntas[i]}») no tiene ${dimensionVector} números finitos`);
  }
});
return preguntas.map((pregunta, i) => ({
  json: {
    pregunta,
    cuerpo: {
      query: ordenados[i].embedding,
      filter: { must: [{ key: 'activo', match: { value: true } }] },
      limit: 10,
      with_payload: true,
      with_vector: false,
    },
  },
}));

// Respuesta 200 de W-3: los 10 mejores puntos por pregunta, sin umbral.
const { coleccion, modeloEmbeddings } = $('Configuración').first().json;
const consultas = $('Validar embeddings').all();
const respuestas = $input.all();
if (respuestas.length !== consultas.length) {
  throw new Error(`Qdrant respondió ${respuestas.length} búsquedas para ${consultas.length} preguntas`);
}
// «Buscar en Qdrant» procesa un ítem por pregunta y conserva el orden.
const resultados = respuestas.map((item, i) => {
  const pregunta = consultas[i].json.pregunta;
  const resp = item.json;
  const points = resp.body?.result?.points;
  if (resp.statusCode !== 200 || !Array.isArray(points)) {
    throw new Error(`Qdrant respondió HTTP ${resp.statusCode} al buscar «${pregunta}»: ${JSON.stringify(resp.body?.status ?? resp.body)}`);
  }
  const puntos = points.map((p) => {
    if (p.payload?.activo !== true) {
      throw new Error(`El punto ${p.id} no está activo y no debía aparecer en «${pregunta}»`);
    }
    return {
      cursoId: p.payload.cursoId,
      nombre: p.payload.nombre,
      categoria: p.payload.categoria,
      score: Math.round(p.score * 10000) / 10000,
    };
  });
  return { pregunta, puntos };
});
return [{ json: { modelo: modeloEmbeddings, coleccion, resultados } }];

// Normaliza el error de cualquier paso para la respuesta 500 de W-3.
const e = $input.first().json.error;
let mensaje = typeof e === 'string' ? e : (e?.message ?? JSON.stringify(e));
if (e && typeof e === 'object' && e.code && !String(mensaje).includes(e.code)) {
  mensaje += ` (${e.code})`;
}
return [{ json: { error: `Falló el paso «${$prevNode.name}»: ${mensaje}` } }];
